1	// Package review — see env.go for package-level rationale.
2	//
3	// picker.go implements the interactive review skills picker and agent selection
4	// helpers. pickConfig presents a huh multi-select per installed agent and saves
5	// the selection to clone-local review preferences.
6	package review
7	
8	import (
9		"context"
10		"errors"
11		"fmt"
12		"io"
13		"log/slog"
14		"os"
15		"sort"
16		"strings"
17	
18		"charm.land/huh/v2"
19	
20		"github.com/entireio/cli/cmd/entire/cli/agent"
21		"github.com/entireio/cli/cmd/entire/cli/agent/skilldiscovery"
22		"github.com/entireio/cli/cmd/entire/cli/agent/types"
23		"github.com/entireio/cli/cmd/entire/cli/logging"
24		reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
25		"github.com/entireio/cli/cmd/entire/cli/settings"
26	)
27	
28	// AgentChoice is one row in the spawn-time picker. Name is the agent
29	// registry key (used for marker/override); Label is the picker-visible
30	// string ("<name>   (N skills configured)" or "<name>   (prompt-only)").
31	type AgentChoice struct {
32		Name  string
33		Label string
34	}
35	
36	// newAccessibleForm creates a huh form with accessibility mode enabled when
37	// the ACCESSIBLE env var is set. Mirrors cli.NewAccessibleForm without
38	// requiring an import of the cli package (which would be circular).
39	func newAccessibleForm(groups ...*huh.Group) *huh.Form {
40		form := huh.NewForm(groups...).WithTheme(huh.ThemeFunc(huh.ThemeDracula))
41		if os.Getenv("ACCESSIBLE") != "" {
42			form = form.WithAccessible(true)
43		}
44		return form
45	}
46	
47	// ConfirmFirstRunSetup prints a banner framing the picker as first-run
48	// setup (rather than the review itself) and waits for the user to confirm.
49	// Returns false if the user cancels; caller should bail gracefully.
50	//
51	// Signposting matters here because `entire review` with no config silently
52	// drops into the picker — users running the command to start a review can
53	// mistake the picker for the review. The banner + confirmation makes the
54	// setup phase explicit, and the trailing "running review now" line in the
55	// caller closes the loop on what comes next.
56	func ConfirmFirstRunSetup(ctx context.Context, out io.Writer) bool {
57		fmt.Fprintln(out, "No review config found — let's set one up first.")
58		fmt.Fprintln(out)
59		fmt.Fprintln(out, "You'll pick skills for each installed agent. They're saved to")
60		fmt.Fprintln(out, "local review preferences; edit later with `entire review --edit`.")
61		fmt.Fprintln(out, "After setup, the review will run with your selection.")
62		fmt.Fprintln(out)
63	
64		proceed := true
65		form := newAccessibleForm(huh.NewGroup(
66			huh.NewConfirm().
67				Title("Set up review skills now?").
68				Affirmative("Yes").
69				Negative("Cancel").
70				Value(&proceed),
71		))
72		if err := form.RunWithContext(ctx); err != nil {
73			fmt.Fprintln(out, "Setup cancelled.")
74			return false
75		}
76		if !proceed {
77			fmt.Fprintln(out, "Setup cancelled.")
78		}
79		return proceed
80	}
81	
82	// RunReviewConfigPicker presents a huh multi-select for each installed agent
83	// that has curated review skills, and saves the selection to
84	// clone-local review preferences. Previously-saved skills are pre-checked via
85	// huh.Option.Selected(true), mirroring how `entire enable` preserves prior
86	// selections in its own agent picker.
87	//
88	// getInstalled is injected to avoid an import cycle with the cli package.
89	func RunReviewConfigPicker(ctx context.Context, out io.Writer, getInstalled func(context.Context) []types.AgentName) (map[string]settings.ReviewConfig, error) {
90		installed := getInstalled(ctx)
91		if len(installed) == 0 {
92			return nil, errors.New(
93				"no agents with hooks installed; " +
94					"run 'entire configure --agent <name>' to install hooks for one, " +
95					"or 'entire enable' to set up the repo",
96			)
97		}
98	
99		// Narrow to agents that have a curated skills list; others need manual
100		// editing of clone-local preferences under review.<agent-name>.
101		type configurableAgent struct {
102			name types.AgentName
103			ag   agent.Agent
104		}
105		var configurable []configurableAgent
106		for _, name := range installed {
107			if !skilldiscovery.IsEligible(string(name)) {
108				continue
109			}
110			ag, err := agent.Get(name)
111			if err != nil {
112				continue
113			}
114			configurable = append(configurable, configurableAgent{name: name, ag: ag})
115		}
116		if len(configurable) == 0 {
117			prefsPath, pathErr := settings.ClonePreferencesPath(ctx)
118			if pathErr != nil {
119				return nil, errors.New(
120					"no installed agents have curated review skills; " +
121						"install an eligible agent and run `entire review --edit`, " +
122						"or edit clone-local review preferences under review.<agent-name>",
123				)
124			}
125			return nil, fmt.Errorf(
126				"no installed agents have curated review skills; "+
127					"install an eligible agent and run `entire review --edit`, "+
128					"or edit clone-local review preferences (%s) under review.<agent-name>",
129				prefsPath,
130			)
131		}
132	
133		// Load existing config so we can pre-check saved skills and seed saved
134		// prompts. A load error here means the settings file is malformed; log
135		// at Warn so users debugging "my saved skills aren't pre-checked" can
136		// see why, but keep going with an empty prefill — runReview already
137		// surfaces the same error distinctly when it's the first load.
138		existing := map[string]settings.ReviewConfig{}
139		existingFixAgent := ""
140		if s, err := settings.Load(ctx); err != nil {
141			logging.Warn(ctx, "settings.Load failed when pre-filling picker", slog.String("error", err.Error()))
142		} else if s != nil {
143			existing = s.Review
144			existingFixAgent = s.ReviewFixAgent
145		}
146	
147		// Up-front header: make the order and count obvious so users can spot
148		// when an agent they expected isn't being offered (e.g., hooks not
149		// installed for it yet).
150		labels := make([]string, 0, len(configurable))
151		for _, c := range configurable {
152			labels = append(labels, string(c.ag.Type()))
153		}
154		fmt.Fprintf(out, "Configuring review for %d agent(s): %s\n", len(configurable), strings.Join(labels, ", "))
155		fmt.Fprintln(out, "(Previously-saved skills are pre-checked. Space to toggle, enter to confirm.)")
156		fmt.Fprintln(out)
157	
158		selected := map[string]settings.ReviewConfig{}
159		for i, c := range configurable {
160			curated := skilldiscovery.CuratedBuiltinsFor(string(c.name))
161	
162			// Discover + dedupe + filter hints.
163			var discovered []agent.DiscoveredSkill
164			if d, ok := c.ag.(agent.SkillDiscoverer); ok {
165				if ds, dErr := d.DiscoverReviewSkills(ctx); dErr == nil {
166					discovered = ds
167				} else {
168					logging.Debug(ctx, "review discovery failed",
169						slog.String("agent", string(c.name)), slog.String("error", dErr.Error()))
170				}
171			}
172			builtinNames := builtinNameSet(curated)
173			discovered = filterOutBuiltinCollisions(discovered, builtinNames)
174	
175			discoveredSet := make(map[string]struct{}, len(discovered))
176			for _, d := range discovered {
177				discoveredSet[d.Name] = struct{}{}
178			}
179			activeHints := skilldiscovery.ActiveInstallHintsFor(string(c.name), discoveredSet)
180	
181			// Pre-populate pick slices from saved config so the picker preselects
182			// them. The header promises "previously-saved skills are pre-checked";
183			// without this split + Option.Selected(true) in BuildReviewPickerFields,
184			// --edit with accept-defaults silently wipes the agent's saved skills.
185			builtinPicks, discoveredPicks := SplitSavedPicks(
186				existing[string(c.name)].Skills, curated, discovered,
187			)
188			prompt := existing[string(c.name)].Prompt
189	
190			fields := BuildReviewPickerFields(
191				string(c.name), curated, discovered, activeHints, prompt,
192				&builtinPicks, &discoveredPicks, &prompt,
193			)
194	
195			// Prepend a non-blocking header Note so the agent being configured
196			// is always clearly visible.
197			header := huh.NewNote().
198				Title(string(c.ag.Type())).
199				Description(fmt.Sprintf("Agent %d of %d · pick review skills and optional instructions", i+1, len(configurable)))
200			fields = append([]huh.Field{header}, fields...)
201	
202			form := newAccessibleForm(huh.NewGroup(fields...))
203			if err := form.RunWithContext(ctx); err != nil {
204				return nil, fmt.Errorf("picker for %s: %w", c.name, err)
205			}
206	
207			cfg := settings.ReviewConfig{
208				Skills: dedupeStrings(append(builtinPicks, discoveredPicks...)),
209				Prompt: strings.TrimSpace(prompt),
210			}
211			if !cfg.IsZero() {
212				selected[string(c.name)] = cfg
213			}
214		}
215		// Merge the picker's output with existing entries the picker could not
216		// surface. Without the merge, save would replace s.Review wholesale and
217		// silently drop entries the user had configured for external agents,
218		// uncurated agents, or agents whose hooks are temporarily uninstalled.
219		offered := make(map[string]struct{}, len(configurable))
220		for _, c := range configurable {
221			offered[string(c.name)] = struct{}{}
222		}
223		merged := MergePickerResults(existing, offered, selected)
224	
225		// The emptiness check runs on `merged`, not `selected`.
226		if len(merged) == 0 {
227			return nil, errors.New("no review skills or prompt configured")
228		}
229	
230		fixAgent, err := pickReviewFixAgentPreference(ctx, merged, existingFixAgent)
231		if err != nil {
232			return nil, err
233		}
234		if err := saveReviewConfigAndFixAgent(ctx, merged, fixAgent); err != nil {
235			return nil, err
236		}
237		fmt.Fprintln(out, "Saved review config to local review preferences. Edit later with `entire review --edit`.")
238		return merged, nil
239	}
240	
241	// MergePickerResults combines the picker's output with existing review
242	// config entries that the picker did not surface. Agents in `offered` are
243	// fully controlled by the picker: if they appear in `selected` with a
244	// non-zero config the entry is set, otherwise the entry is removed.
245	// Agents not in `offered` keep their existing config untouched.
246	//
247	// Exported so tests can drive it directly — the picker itself
248	// can't run headless.
249	func MergePickerResults(existing map[string]settings.ReviewConfig, offered map[string]struct{}, selected map[string]settings.ReviewConfig) map[string]settings.ReviewConfig {
250		merged := make(map[string]settings.ReviewConfig, len(existing)+len(selected))
251		for name, cfg := range existing {
252			if _, wasOffered := offered[name]; !wasOffered {
253				merged[name] = cfg
254			}
255		}
256		for name, cfg := range selected {
257			merged[name] = cfg
258		}
259		return merged
260	}
261	
262	// SaveReviewConfig persists the review map into clone-local preferences while
263	// preserving other review preferences. A load error means the preferences file
264	// exists but is malformed — we must NOT silently overwrite it with an empty
265	// struct, or every unrelated review preference would be wiped. Return the
266	// error so the caller can surface it instead.
267	func SaveReviewConfig(ctx context.Context, review map[string]settings.ReviewConfig) error {
268		prefs, err := settings.LoadClonePreferences(ctx)
269		if err != nil {
270			return fmt.Errorf("load review preferences before save: %w", err)
271		}
272		if prefs == nil {
273			prefs = &settings.ClonePreferences{}
274		}
275		prefs.Review = review
276		if err := settings.SaveClonePreferences(ctx, prefs); err != nil {
277			return fmt.Errorf("save review preferences: %w", err)
278		}
279		return nil
280	}
281	
282	func SaveReviewFixAgent(ctx context.Context, agentName string) error {
283		prefs, err := settings.LoadClonePreferences(ctx)
284		if err != nil {
285			return fmt.Errorf("load review preferences before save: %w", err)
286		}
287		if prefs == nil {
288			prefs = &settings.ClonePreferences{}
289		}
290		prefs.ReviewFixAgent = agentName
291		if err := settings.SaveClonePreferences(ctx, prefs); err != nil {
292			return fmt.Errorf("save review preferences: %w", err)
293		}
294		return nil
295	}
296	
297	func saveReviewConfigAndFixAgent(ctx context.Context, review map[string]settings.ReviewConfig, fixAgent string) error {
298		prefs, err := settings.LoadClonePreferences(ctx)
299		if err != nil {
300			return fmt.Errorf("load review preferences before save: %w", err)
301		}
302		if prefs == nil {
303			prefs = &settings.ClonePreferences{}
304		}
305		prefs.Review = review
306		prefs.ReviewFixAgent = fixAgent
307		if err := settings.SaveClonePreferences(ctx, prefs); err != nil {
308			return fmt.Errorf("save review preferences: %w", err)
309		}
310		return nil
311	}
312	
313	func pickReviewFixAgentPreference(ctx context.Context, review map[string]settings.ReviewConfig, current string) (string, error) {
314		choices := reviewFixAgentChoices(review)
315		switch len(choices) {
316		case 0:
317			return current, nil
318		case 1:
319			return choices[0].Name, nil
320		default:
321			return promptForReviewFixAgent(ctx, choices, current)
322		}
323	}
324	
325	// ComputeEligibleConfigured returns the sorted list of agents that are both
326	// configured (non-zero ReviewConfig entry) AND have hooks installed. Only
327	// eligible agents are valid picker targets — spawning a review for an agent
328	// without hooks would silently drop the review metadata.
329	func ComputeEligibleConfigured(s *settings.EntireSettings, installed []types.AgentName) []AgentChoice {
330		if s == nil {
331			return nil
332		}
333		installedSet := make(map[types.AgentName]struct{}, len(installed))
334		for _, name := range installed {
335			installedSet[name] = struct{}{}
336		}
337		out := make([]AgentChoice, 0, len(s.Review))
338		for name, cfg := range s.Review {
339			if cfg.IsZero() {
340				continue
341			}
342			if _, ok := installedSet[types.AgentName(name)]; !ok {
343				continue
344			}
345			out = append(out, AgentChoice{Name: name, Label: labelForAgentChoice(name, cfg)})
346		}
347		sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
348		return out
349	}
350	
351	// labelForAgentChoice builds the picker-visible label for an agent row.
352	func labelForAgentChoice(name string, cfg settings.ReviewConfig) string {
353		switch {
354		case len(cfg.Skills) > 0:
355			return fmt.Sprintf("%s   (%d skills configured)", name, len(cfg.Skills))
356		case cfg.Prompt != "":
357			return name + "   (prompt-only)"
358		default:
359			return name
360		}
361	}
362	
363	// computeLaunchableEligible returns the subset of ComputeEligibleConfigured
364	// that also have a non-nil AgentReviewer (i.e., are launchable by the CLI).
365	// Used by the dispatch fork in cmd.go to decide whether to route to the
366	// multi-agent path.
367	//
368	// reviewerFor is deps.ReviewerFor injected at the cmd layer; it returns nil
369	// for non-launchable agents (cursor, opencode, factoryai-droid, copilot-cli).
370	func computeLaunchableEligible(
371		s *settings.EntireSettings,
372		installed []types.AgentName,
373		reviewerFor func(string) reviewtypes.AgentReviewer,
374	) []AgentChoice {
375		eligible := ComputeEligibleConfigured(s, installed)
376		out := make([]AgentChoice, 0, len(eligible))
377		for _, c := range eligible {
378			if reviewerFor(c.Name) != nil {
379				out = append(out, c)
380			}
381		}
382		return out
383	}
384	
385	// PromptForAgent renders the single-select agent picker shown when more than
386	// one eligible agent is configured. Returns the chosen agent name. Respects
387	// accessibility mode via newAccessibleForm.
388	func PromptForAgent(ctx context.Context, eligible []AgentChoice) (string, error) {
389		if err := ctx.Err(); err != nil {
390			return "", fmt.Errorf("agent picker: %w", err)
391		}
392		if len(eligible) == 0 {
393			return "", errors.New("no eligible agents to prompt for")
394		}
395		options := make([]huh.Option[string], 0, len(eligible))
396		for _, c := range eligible {
397			options = append(options, huh.NewOption(c.Label, c.Name))
398		}
399		picked := eligible[0].Name
400		form := newAccessibleForm(huh.NewGroup(
401			huh.NewSelect[string]().
402				Title("Which agent should run this review?").
403				Options(options...).
404				Value(&picked),
405		))
406		if err := form.RunWithContext(ctx); err != nil {
407			return "", fmt.Errorf("agent picker: %w", err)
408		}
409		return picked, nil
410	}
411	
412	// SelectReviewAgent picks an agent from the configured review map.
413	//
414	// If override is non-empty, returns the config for that agent or an error
415	// listing the configured alternatives. Otherwise returns the alphabetically
416	// first configured agent — deterministic but user-overridable via --agent.
417	func SelectReviewAgent(review map[string]settings.ReviewConfig, override string) (string, settings.ReviewConfig, error) {
418		if len(review) == 0 {
419			return "", settings.ReviewConfig{}, errors.New("no review config found")
420		}
421		var names []string
422		for name, cfg := range review {
423			if !cfg.IsZero() {
424				names = append(names, name)
425			}
426		}
427		if len(names) == 0 {
428			return "", settings.ReviewConfig{}, errors.New("no review config found")
429		}
430		sort.Strings(names)
431		if override != "" {
432			if cfg, ok := review[override]; ok && !cfg.IsZero() {
433				return override, cfg, nil
434			}
435			return "", settings.ReviewConfig{}, fmt.Errorf(
436				"agent %q is not configured for review; configured agents: %s",
437				override, strings.Join(names, ", "),
438			)
439		}
440		pick := names[0]
441		return pick, review[pick], nil
442	}
443	
444	// VerifyConfiguredSkillsInstalled is the spawn-time backstop for the
445	// silent-failure vector. For each skill in cfg.Skills, check it's either a
446	// curated built-in or returned by the agent's SkillDiscoverer; fail with a
447	// user-facing error if any skill is missing. Empty Skills (prompt-only
448	// config) short-circuits to nil — a freeform prompt has no skill list to
449	// validate against.
450	func VerifyConfiguredSkillsInstalled(ctx context.Context, ag agent.Agent, cfg settings.ReviewConfig) error {
451		if len(cfg.Skills) == 0 {
452			return nil
453		}
454		builtins := builtinNameSet(skilldiscovery.CuratedBuiltinsFor(string(ag.Name())))
455		discoveredNames := map[string]struct{}{}
456		if d, ok := ag.(agent.SkillDiscoverer); ok {
457			if skills, err := d.DiscoverReviewSkills(ctx); err == nil {
458				for _, s := range skills {
459					discoveredNames[s.Name] = struct{}{}
460				}
461			} else {
462				logging.Debug(ctx, "skill verification discovery failed",
463					slog.String("agent", string(ag.Name())), slog.String("error", err.Error()))
464			}
465		}
466		var missing []string
467		for _, s := range cfg.Skills {
468			if _, ok := builtins[s]; ok {
469				continue
470			}
471			if _, ok := discoveredNames[s]; ok {
472				continue
473			}
474			missing = append(missing, s)
475		}
476		if len(missing) == 0 {
477			return nil
478		}
479		return fmt.Errorf(
480			"configured review skill(s) not installed: %s\n"+
481				"run `entire review --edit` to reconfigure, or install the plugin and retry",
482			strings.Join(missing, ", "),
483		)
484	}
485	
486	// BuildReviewPickerFields composes the per-agent group fields for the
487	// review picker. Returns a slice of huh.Field in render order:
488	//
489	//	0: built-in commands (multiselect) OR note
490	//	1: installed plugin skills (multiselect) OR note
491	//	2: install hints (note with all active hint messages) — OMITTED if empty
492	//	3: additional instructions (text) — always present
493	func BuildReviewPickerFields(
494		agentName string,
495		builtins []skilldiscovery.CuratedSkill,
496		discovered []agent.DiscoveredSkill,
497		activeHints []skilldiscovery.InstallHint,
498		previousPrompt string,
499		builtinPicksOut, discoveredPicksOut *[]string,
500		promptOut *string,
501	) []huh.Field {
502		var fields []huh.Field
503	
504		if builtinPicksOut != nil && len(*builtinPicksOut) == 0 &&
505			len(builtins) == 1 && strings.TrimSpace(previousPrompt) == "" {
506			*builtinPicksOut = []string{builtins[0].Name}
507		}
508	
509		builtinPreselected := preselectedSet(builtinPicksOut)
510		discoveredPreselected := preselectedSet(discoveredPicksOut)
511	
512		if len(builtins) > 0 {
513			opts := make([]huh.Option[string], 0, len(builtins))
514			for _, b := range builtins {
515				opt := huh.NewOption(b.Name, b.Name)
516				if _, ok := builtinPreselected[b.Name]; ok {
517					opt = opt.Selected(true)
518				}
519				opts = append(opts, opt)
520			}
521			ms := huh.NewMultiSelect[string]().
522				Title("Built-in commands").
523				Options(opts...).
524				Height(len(opts) + 1)
525			if builtinPicksOut != nil {
526				ms = ms.Value(builtinPicksOut)
527			}
528			fields = append(fields, ms)
529		} else {
530			fields = append(fields, huh.NewNote().
531				Title("Built-in commands").
532				Description(fmt.Sprintf("No built-in review commands in %s.", agentName)))
533		}
534	
535		if len(discovered) > 0 {
536			opts := make([]huh.Option[string], 0, len(discovered))
537			for _, d := range discovered {
538				opt := huh.NewOption(d.Name, d.Name)
539				if _, ok := discoveredPreselected[d.Name]; ok {
540					opt = opt.Selected(true)
541				}
542				opts = append(opts, opt)
543			}
544			ms := huh.NewMultiSelect[string]().
545				Title("Installed plugin skills").
546				Options(opts...).
547				Height(len(opts) + 1)
548			if discoveredPicksOut != nil {
549				ms = ms.Value(discoveredPicksOut)
550			}
551			fields = append(fields, ms)
552		} else {
553			fields = append(fields, huh.NewNote().
554				Title("Installed plugin skills").
555				Description("No plugin review skills detected on disk."))
556		}
557	
558		if len(activeHints) > 0 {
559			var sb strings.Builder
560			for i, h := range activeHints {
561				if i > 0 {
562					sb.WriteString("\n")
563				}
564				sb.WriteString("• ")
565				sb.WriteString(h.Message)
566			}
567			fields = append(fields, huh.NewNote().
568				Title("Install more").
569				Description(sb.String()))
570		}
571	
572		text := huh.NewText().
573			Title("Additional instructions (optional)").
574			Description("Added after selected skills. If no skills are selected, this becomes the full review prompt.")
575		if promptOut != nil {
576			*promptOut = previousPrompt
577			text = text.Value(promptOut)
578		}
579		fields = append(fields, text)
580	
581		return fields
582	}
583	
584	// SplitSavedPicks partitions a flat saved-skills list into the subset that
585	// matches built-in curated commands and the subset that matches discovered
586	// plugin skills. Skill names that match neither are dropped from both — they're
587	// preserved on the settings side via MergePickerResults when they belong to a
588	// picker-unaware agent entry.
589	func SplitSavedPicks(saved []string, builtins []skilldiscovery.CuratedSkill, discovered []agent.DiscoveredSkill) ([]string, []string) {
590		builtinNames := make(map[string]struct{}, len(builtins))
591		for _, b := range builtins {
592			builtinNames[b.Name] = struct{}{}
593		}
594		discoveredNames := make(map[string]struct{}, len(discovered))
595		for _, d := range discovered {
596			discoveredNames[d.Name] = struct{}{}
597		}
598		var builtinPicks, discoveredPicks []string
599		for _, s := range saved {
600			if _, ok := builtinNames[s]; ok {
601				builtinPicks = append(builtinPicks, s)
602				continue
603			}
604			if _, ok := discoveredNames[s]; ok {
605				discoveredPicks = append(discoveredPicks, s)
606			}
607		}
608		return builtinPicks, discoveredPicks
609	}
610	
611	// preselectedSet turns a slice pointer's current contents into a lookup
612	// set for the picker's "previously-saved" pre-selection.
613	func preselectedSet(slice *[]string) map[string]struct{} {
614		if slice == nil || len(*slice) == 0 {
615			return nil
616		}
617		out := make(map[string]struct{}, len(*slice))
618		for _, s := range *slice {
619			out[s] = struct{}{}
620		}
621		return out
622	}
623	
624	func builtinNameSet(curated []skilldiscovery.CuratedSkill) map[string]struct{} {
625		set := make(map[string]struct{}, len(curated))
626		for _, c := range curated {
627			set[c.Name] = struct{}{}
628		}
629		return set
630	}
631	
632	// filterOutBuiltinCollisions drops any discovered skill whose name collides
633	// with a curated built-in. Built-in wins because it carries a richer,
634	// hand-authored description.
635	func filterOutBuiltinCollisions(discovered []agent.DiscoveredSkill, builtins map[string]struct{}) []agent.DiscoveredSkill {
636		if len(discovered) == 0 || len(builtins) == 0 {
637			return discovered
638		}
639		out := make([]agent.DiscoveredSkill, 0, len(discovered))
640		for _, d := range discovered {
641			if _, clash := builtins[d.Name]; clash {
642				continue
643			}
644			out = append(out, d)
645		}
646		return out
647	}
648	
649	func dedupeStrings(xs []string) []string {
650		if len(xs) == 0 {
651			return xs
652		}
653		seen := make(map[string]struct{}, len(xs))
654		out := make([]string, 0, len(xs))
655		for _, x := range xs {
656			if _, ok := seen[x]; ok {
657				continue
658			}
659			seen[x] = struct{}{}
660			out = append(out, x)
661		}
662		return out
663	}
