// migrateLegacyRoles upgrades pre-role ReviewConfig entries. See the
// review.MigrateLegacyRoles wrapper for the rules. Returns true if any
// entry was modified; callers should persist s when true.
func migrateLegacyRoles(s *EntireSettings) bool {
    if s == nil || len(s.Review) == 0 { return false }
