```go
func runPostReviewFixPrompt(ctx context.Context, cmd *cobra.Command, s *settings.EntireSettings, manifest LocalReviewManifest, perRunPrompt string) error {
    out := cmd.OutOrStdout()
    if len(manifest.Sources) == 0 || findingsCount(manifest) == 0 {
        return nil
    }
    fixer := FixerOf(s)
    if fixer == "" {
        // No fixer configured — print non-fix pointer.
        printFindingsFooter(out, manifest)
        return nil
    }

    // Always-mode bypasses the prompt.
    if s.FixAfterReview == settings.FixAfterReviewAlways {
        return launchFixFromManifest(ctx, cmd, manifest, fixer, perRunPrompt, /*all=*/ true)
    }

    // Non-interactive: print pointer and exit.
    if !interactive.CanPromptInteractively() {
        printFindingsFooter(out, manifest)
        return nil
    }

    // Render prompt header.
    fmt.Fprintf(out, "\nApply %d fixes now with %s?\n", findingsCount(manifest), fixer)
    fmt.Fprintln(out, "  [Y]es  ·  [s]elect fixes  ·  [n]o  ·  [A]lways")

    choice, err := ReadSingleKey(os.Stdin, KeyChoice{Default: 'Y', Allowed: "YsnA"})
    if err != nil { return err }
    switch choice {
    case 'Y':
        return launchFixFromManifest(ctx, cmd, manifest, fixer, perRunPrompt, /*all=*/ true)
    case 's':
        return runReviewFix(ctx, cmd, reviewManifestHandle(manifest), false, fixer, deps.NewSilentError)
    case 'n':
        printFindingsFooter(out, manifest)
        return nil
    case 'A':
        // Persist preference, then run.
        s.FixAfterReview = settings.FixAfterReviewAlways
        if err := saveSettingsPreference(ctx, s); err != nil {
            fmt.Fprintln(cmd.ErrOrStderr(), "warning: could not persist 'always' preference:", err)
        }
        return launchFixFromManifest(ctx, cmd, manifest, fixer, perRunPrompt, /*all=*/ true)
    }
    return nil
}

func printFindingsFooter(w io.Writer, m LocalReviewManifest) {
    handle := reviewManifestHandle(m)
    fmt.Fprintln(w, "\nSkipped. Findings preserved on disk.")
    fmt.Fprintln(w)
    fmt.Fprintf(w, "Run: entire review fix %s            apply when ready\n", "")
    fmt.Fprintf(w, "     entire review fix %s --all      apply all, skip picker\n", "")
    fmt.Fprintln(w, "     entire review findings         just browse the report")
}
```

`launchFixFromManifest` wraps `launchReviewFixAgent` with the manifest's prompt + the per-run prompt.

