func TestReviewer_EmitsTokensOnEachUsageBearingEnvelope(t *testing.T) {
    t.Parallel()
    fixture, err := os.Open("testdata/stream_with_deltas.jsonl")
    if err != nil { t.Fatal(err) }
    defer fixture.Close()

    events := parseClaudeStream(fixture) // exposed test helper
    var tokens []reviewtypes.Tokens
    for _, e := range events {
        if t, ok := e.(reviewtypes.Tokens); ok { tokens = append(tokens, t) }
    }
    if len(tokens) < 2 {
        t.Errorf("expected multiple Tokens events (one per assistant + final), got %d", len(tokens))
    }
    // Each Tokens event should be monotonically non-decreasing in (In + Out).
    for i := 1; i < len(tokens); i++ {
        prev := tokens[i-1].In + tokens[i-1].Out
        curr := tokens[i].In + tokens[i].Out
        if curr < prev {
            t.Errorf("tokens went backwards at event %d: %d → %d", i, prev, curr)
        }
    }
}
