```go
// Role expresses how a configured agent participates in `entire review`.
// Stored as a string for stable JSON encoding; consumers should compare
// against the Role* constants below rather than untyped strings.
type Role string

const (
    // RoleReviewer means the agent runs on `entire review`. Multiple
    // agents may have this role; they run in parallel.
    RoleReviewer Role = "reviewer"

    // RoleFixer means the agent runs on `entire review fix`. Exactly one
    // agent across the configured map may have RoleFixer or RoleBoth.
    RoleFixer Role = "fixer"

    // RoleBoth means the agent reviews AND fixes. Counts toward the
    // single-fixer cap.
    RoleBoth Role = "both"

    // RoleSkip means the agent is configured but not used by review.
    // Useful when the user wants to keep saved skills without enrolling.
    RoleSkip Role = "skip"
)

// Valid reports whether r is a recognized role. The empty string is
// considered valid because legacy ReviewConfig entries written before
// roles existed have no role field; NormalizeRoles assigns Reviewer to
// such entries on first load.
func (r Role) Valid() bool {
    switch r {
    case "", RoleReviewer, RoleFixer, RoleBoth, RoleSkip:
        return true
    }
    return false
}

// IsFixer reports whether r entitles an agent to be the Fixer.
func (r Role) IsFixer() bool { return r == RoleFixer || r == RoleBoth }

// IsReviewer reports whether r entitles an agent to participate as a Reviewer.
func (r Role) IsReviewer() bool { return r == RoleReviewer || r == RoleBoth }
```

