```go
// Package review — see env.go for package-level rationale.
//
// roles.go provides role helpers for the post-redesign review settings:
// NormalizeRoles enforces invariants, MigrateLegacyRoles upgrades
// pre-role configs, ReviewersOf and FixerOf are query helpers used by
// runReview and runReviewFix.
package review

import (
    "sort"

    "github.com/entireio/cli/cmd/entire/cli/settings"
)

// NormalizeRoles enforces the at-most-one-fixer invariant. Empty roles
// are upgraded to Reviewer. If two or more agents claim Fixer or Both,
// the alphabetically-first wins; the rest are demoted to Reviewer.
// Returns a new map; the input is not mutated.
func NormalizeRoles(in map[string]settings.ReviewConfig) map[string]settings.ReviewConfig {
    if len(in) == 0 {
        return in
    }
    out := make(map[string]settings.ReviewConfig, len(in))
    var fixerCandidates []string
    for name, cfg := range in {
        if cfg.Role == "" {
            cfg.Role = settings.RoleReviewer
        }
        if cfg.Role.IsFixer() {
            fixerCandidates = append(fixerCandidates, name)
        }
        out[name] = cfg
    }
    if len(fixerCandidates) > 1 {
        sort.Strings(fixerCandidates)
        winner := fixerCandidates[0]
        for _, loser := range fixerCandidates[1:] {
            cfg := out[loser]
            // Demote: Both → Reviewer, Fixer → Reviewer.
            cfg.Role = settings.RoleReviewer
            out[loser] = cfg
        }
        // Ensure the winner's role is preserved as-is (Fixer or Both).
        _ = winner // no mutation needed; documents intent.
    }
    return out
}

// MigrateLegacyRoles inspects s for pre-role configs and assigns roles
// based on the legacy ReviewFixAgent field. Idempotent: re-running on
// an already-migrated settings struct is a no-op (returns false).
//
// Migration rules:
//   - Entries with non-empty Role are left untouched.
//   - The agent named in s.ReviewFixAgent becomes:
//       - RoleBoth if it has Skills or Prompt configured (it reviewed AND fixed)
//       - RoleFixer otherwise (it was a fix-only agent)
//   - All other entries with empty Role become RoleReviewer.
//
// Caller is responsible for saving s after migration runs.
func MigrateLegacyRoles(s *settings.EntireSettings) bool {
    if s == nil || len(s.Review) == 0 {
        return false
    }
    anyEmpty := false
    for _, cfg := range s.Review {
        if cfg.Role == "" {
            anyEmpty = true
            break
        }
    }
    if !anyEmpty {
        return false
    }
    fixAgent := s.ReviewFixAgent
    for name, cfg := range s.Review {
        if cfg.Role != "" {
            continue
        }
        if name == fixAgent {
            if len(cfg.Skills) > 0 || cfg.Prompt != "" {
                cfg.Role = settings.RoleBoth
            } else {
                cfg.Role = settings.RoleFixer
            }
        } else {
            cfg.Role = settings.RoleReviewer
        }
        s.Review[name] = cfg
    }
    return true
}

// ReviewersOf returns the sorted set of agent names with RoleReviewer
// or RoleBoth. The result is what `entire review` runs.
func ReviewersOf(s *settings.EntireSettings) []string {
    if s == nil { return nil }
    var out []string
    for name, cfg := range s.Review {
        if cfg.Role.IsReviewer() {
            out = append(out, name)
        }
    }
    sort.Strings(out)
    return out
}

// FixerOf returns the agent name with RoleFixer or RoleBoth. Returns
// the empty string if no agent is configured as a Fixer. Assumes
// NormalizeRoles has been called; if multiple agents claim Fixer/Both,
// returns the alphabetically-first to stay deterministic.
func FixerOf(s *settings.EntireSettings) string {
    if s == nil { return "" }
    var candidates []string
    for name, cfg := range s.Review {
        if cfg.Role.IsFixer() {
            candidates = append(candidates, name)
        }
    }
    if len(candidates) == 0 { return "" }
    sort.Strings(candidates)
    return candidates[0]
}
```

