package settings

import "sort"

// migrateLegacyRoles upgrades pre-role ReviewConfig entries. See the
// review.MigrateLegacyRoles wrapper for the rules. Returns true if any
// entry was modified; callers should persist s when true.
func migrateLegacyRoles(s *EntireSettings) bool {
    if s == nil || len(s.Review) == 0 { return false }
    anyEmpty := false
    for _, cfg := range s.Review {
        if cfg.Role == "" { anyEmpty = true; break }
    }
    if !anyEmpty { return false }
    for name, cfg := range s.Review {
        if cfg.Role != "" { continue }
        if name == s.ReviewFixAgent {
            if len(cfg.Skills) > 0 || cfg.Prompt != "" {
                cfg.Role = RoleBoth
            } else {
                cfg.Role = RoleFixer
            }
        } else {
            cfg.Role = RoleReviewer
        }
        s.Review[name] = cfg
    }
    // Enforce at-most-one-fixer.
    var fixers []string
    for name, cfg := range s.Review {
        if cfg.Role.IsFixer() { fixers = append(fixers, name) }
    }
    if len(fixers) > 1 {
        sort.Strings(fixers)
        for _, loser := range fixers[1:] {
            cfg := s.Review[loser]
            cfg.Role = RoleReviewer
            s.Review[loser] = cfg
        }
    }
    return true
}
