```go
package review

import (
    "bufio"
    "fmt"
    "io"
    "strings"
)

type KeyChoice struct {
    Default rune   // returned when stdin is non-interactive or user just presses Enter
    Allowed string // case-insensitive set; rune that lands here is normalized to its appearance in this string
}

// ReadSingleKey reads from r until it gets a rune matching one of Allowed
// (case-insensitive) or EOF. On EOF / non-TTY, returns Default. Whitespace
// is skipped. Unknown keys are silently swallowed.
//
// The returned rune is in the case used inside Allowed (so callers can
// distinguish Y (yes) from y (yes-case-irrelevant) at the call site if they
// want; mostly Allowed is "YsnA" matching the [Y]/[s]/[n]/[A] mockup).
func ReadSingleKey(r io.Reader, choice KeyChoice) (rune, error) {
    if r == nil { return choice.Default, nil }
    br := bufio.NewReader(r)
    for {
        b, _, err := br.ReadRune()
        if err == io.EOF { return choice.Default, nil }
        if err != nil { return 0, fmt.Errorf("read key: %w", err) }
        if b == '\n' || b == '\r' { return choice.Default, nil }
        if b == ' ' || b == '\t' { continue }
        // Normalize: find b in Allowed case-insensitively.
        for _, a := range choice.Allowed {
            if a == b || (strings.ToLower(string(a)) == strings.ToLower(string(b))) {
                return a, nil
            }
        }
        // Unknown key — loop and read another.
    }
}
```

