package review

import (
    "context"
    "fmt"
    "io"
    "strings"

    "charm.land/huh/v2"

    "github.com/entireio/cli/cmd/entire/cli/interactive"
)

// askPerRunPrompt asks the user for optional one-off context. Returns
// "" when the user submits empty input. Returns "" silently when stdin
// isn't promptable (CI / piped input).
func askPerRunPrompt(ctx context.Context, out io.Writer) string {
    if !interactive.CanPromptInteractively() {
        return ""
    }
    var value string
    form := newAccessibleForm(huh.NewGroup(
        huh.NewInput().
            Title("Add context for this run?").
            Description("Optional — ↩ to skip").
            Value(&value),
    ))
    if err := form.RunWithContext(ctx); err != nil {
        // Cancellation = no per-run prompt; review proceeds.
        return ""
    }
    return strings.TrimSpace(value)
}
```

