```go
package review

import (
    "bufio"
    "fmt"
    "io"
    "strings"
    "unicode"
)

type KeyChoice struct {
    Default rune
    Allowed string
}

// ReadSingleKey reads from r until a rune matching one of Allowed
// (case-insensitive) or EOF. On EOF or newline, returns Default.
// Whitespace (other than newline) is skipped. Unknown runes are
// swallowed. Returned rune is in the case that appears in Allowed.
func ReadSingleKey(r io.Reader, choice KeyChoice) (rune, error) {
    if r == nil { return choice.Default, nil }
    br := bufio.NewReader(r)
    for {
        b, _, err := br.ReadRune()
        if err == io.EOF { return choice.Default, nil }
        if err != nil { return 0, fmt.Errorf("read key: %w", err) }
        if b == '\n' || b == '\r' { return choice.Default, nil }
        if unicode.IsSpace(b) { continue }
        for _, a := range choice.Allowed {
            if unicode.ToLower(a) == unicode.ToLower(b) { return a, nil }
        }
        // Unknown — try next rune.
    }
}

// Allowed is documentation: capitalization of each rune is how it'll be
// returned. Conventionally: capital letter = default-shown form.
//
// Examples:
//   KeyChoice{Default: 'Y', Allowed: "YsnA"}  → 'Y'/'s'/'n'/'A'
//   KeyChoice{Default: 'n', Allowed: "Yn"}    → 'Y' or 'n'
var _ = (*strings.Reader)(nil) // import-pin
```

