```go
// findingsCount sums findings across all sources in a manifest. Used by
// the fix prompt header.
func findingsCount(m LocalReviewManifest) int {
    total := 0
    for _, src := range m.Sources {
        total += len(src.Findings)
    }
    return total
}

// FixLauncher is the production launcher; tests inject a stub.
type FixLauncher func(ctx context.Context, cmd *cobra.Command, manifest LocalReviewManifest, agentName, perRunPrompt string, all bool) error

// launchFixFromManifest composes the manifest's prompt + the per-run
// prompt and calls launchReviewFixAgent. Single-source helper used by
// both the [Y] and [A] branches of the inline prompt.
func launchFixFromManifest(ctx context.Context, cmd *cobra.Command, manifest LocalReviewManifest, fixer, perRunPrompt string, all bool) error {
    sources := manifest.Sources
    if !all {
        // [s] / interactive picker — delegate to runReviewFix
        // with target=manifest handle.
        return runReviewFix(ctx, cmd, reviewManifestHandle(manifest), false, fixer, perRunPrompt, /*silent=*/ nil)
    }
    prompt := composeAllFindingsFixPrompt(sources) // existing helper in fix.go
    if perRunPrompt != "" {
        prompt += "\n\nAdditional context for this run:\n" + perRunPrompt
    }
    return launchReviewFixAgent(ctx, fixer, prompt)
}

// printFindingsFooter prints the consolidated Run: block shown when the
// user picks [n] or when stdin isn't promptable.
func printFindingsFooter(w io.Writer, m LocalReviewManifest) {
    fmt.Fprintln(w)
    fmt.Fprintln(w, "Skipped. Findings preserved on disk.")
    fmt.Fprintln(w)
    fmt.Fprintln(w, "Run: entire review fix            apply when ready")
    fmt.Fprintln(w, "     entire review fix --all      apply all, skip picker")
    fmt.Fprintln(w, "     entire review findings       just browse the report")
}

// RunPostReviewFixPrompt is the end-of-review UX entrypoint. Called by
// runReview / runMultiAgentPath after the manifest is written. Always
// returns nil on the "skip" or "no findings" paths; only returns an
// error if the fix launch itself errored.
func RunPostReviewFixPrompt(
    ctx context.Context,
    cmd *cobra.Command,
    s *settings.EntireSettings,
    manifest LocalReviewManifest,
    perRunPrompt string,
    silentErr func(error) error,
) error {
    out := cmd.OutOrStdout()
    if findingsCount(manifest) == 0 { return nil }

    fixer := FixerOf(s)
    if fixer == "" {
        fmt.Fprintln(out)
        fmt.Fprintln(out, "Found findings, but no Fixer is configured.")
        fmt.Fprintln(out, "Run: entire review setup")
        return nil
    }

    if s.FixAfterReview == settings.FixAfterReviewAlways {
        return launchFixFromManifest(ctx, cmd, manifest, fixer, perRunPrompt, /*all=*/ true)
    }

    if !interactive.CanPromptInteractively() {
        printFindingsFooter(out, manifest)
        return nil
    }

    fmt.Fprintf(out, "\nApply %d fixes now with %s?\n", findingsCount(manifest), displayLabelFor(fixer))
    fmt.Fprintln(out, "  [Y]es  ·  [s]elect fixes  ·  [n]o  ·  [A]lways")
    choice, err := ReadSingleKey(os.Stdin, KeyChoice{Default: 'Y', Allowed: "YsnA"})
    if err != nil { return fmt.Errorf("read fix-prompt key: %w", err) }
    switch choice {
    case 'Y':
        return launchFixFromManifest(ctx, cmd, manifest, fixer, perRunPrompt, /*all=*/ true)
    case 's':
        return launchFixFromManifest(ctx, cmd, manifest, fixer, perRunPrompt, /*all=*/ false)
    case 'n':
        printFindingsFooter(out, manifest)
        return nil
    case 'A':
        s.FixAfterReview = settings.FixAfterReviewAlways
        if err := settings.Save(ctx, s); err != nil {
            fmt.Fprintln(cmd.ErrOrStderr(), "warning: could not persist 'always' preference:", err)
        }
        return launchFixFromManifest(ctx, cmd, manifest, fixer, perRunPrompt, /*all=*/ true)
    }
    return nil
}
```

