func PrintSetupBanner(w io.Writer, review map[string]settings.ReviewConfig) {
    var reviewers, fixers, skipped []string
    for name, cfg := range review {
        switch {
        case cfg.Role.IsReviewer() && !cfg.Role.IsFixer():
            reviewers = append(reviewers, displayLabelFor(name))
        case cfg.Role == settings.RoleBoth:
            reviewers = append(reviewers, displayLabelFor(name))
            fixers = append(fixers, displayLabelFor(name))
        case cfg.Role == settings.RoleFixer:
            fixers = append(fixers, displayLabelFor(name))
        case cfg.Role == settings.RoleSkip:
            skipped = append(skipped, displayLabelFor(name))
        }
    }
    sort.Strings(reviewers); sort.Strings(fixers); sort.Strings(skipped)

    fmt.Fprintln(w, "✓ Saved to .entire/settings.json")
    fmt.Fprintln(w)
    if len(reviewers) == 0 {
        fmt.Fprintln(w, "  Reviewers: (none — `entire review` will exit)")
    } else if len(reviewers) == 1 {
        fmt.Fprintf(w, "  Reviewer:  %s\n", reviewers[0])
    } else {
        fmt.Fprintf(w, "  Reviewers: %s\n", strings.Join(reviewers, ", "))
    }
    if len(fixers) == 1 {
