// BuildPickRolesFields constructs one huh.Select per agent. Each
// Select binds to the pointer in ptrs[agent], so callers can read back
// the user's selection by dereferencing *ptrs[agent] after the form runs.
func BuildPickRolesFields(agents []string, ptrs map[string]*settings.Role) []huh.Field {
    fields := make([]huh.Field, 0, len(agents))
    opts := []huh.Option[settings.Role]{
        huh.NewOption("Reviewer", settings.RoleReviewer).Description("Runs on `entire review`. Multiple agents allowed."),
        huh.NewOption("Fixer", settings.RoleFixer).Description("Runs on `entire review fix`. Exactly one across the config."),
